const chatId = msg && msg.payload ? msg.payload.chatId : undefined;
const rawContent = msg && msg.payload ? msg.payload.content : undefined;
const text = typeof rawContent === 'string' ? rawContent.trim() : '';
const stateKey = `state_${chatId ?? 'unknown'}`;
const state = flow.get(stateKey) || null;

function log(step, summary) {
    node.warn(`${new Date().toISOString()} | chat=${chatId ?? 'unknown'} | ${step} | ${summary}`);
}

log('router:input_received', `state=${state ?? 'none'} content=${JSON.stringify(text.slice(0, 80))}`);

// /start must work from any branch. Telegram can append a payload to /start.
if (/^\/start(?:@\w+)?(?:\s.*)?$/i.test(text)) {
    flow.set(stateKey, null);
    log('menu:opened', 'source=/start');
    return [msg, null, null, null, null, null];
}

if (/^\/menu(?:@\w+)?$/i.test(text) || text === 'back' || text === 'menu') {
    flow.set(stateKey, null);
    log('menu:opened', 'source=back_or_menu');
    return [msg, null, null, null, null, null];
}

if (text === 'calc') {
    flow.set(stateKey, 'calc');
    log('calc:started', 'calculator mode enabled');
    return [null, msg, null, null, null, null];
}

if (text === 'currency') {
    flow.set(stateKey, null);
    log('nbu:selected', 'currency menu item');
    return [null, null, null, msg, null, null];
}

if (text === 'about') {
    flow.set(stateKey, null);
    log('about:opened', 'about menu item');
    return [null, null, null, null, msg, null];
}

// While in calculator mode, every other inbound message is treated as calculator input.
// Empty/undefined content is deliberately passed to validation too.
if (state === 'calc') {
    return [null, null, msg, null, null, null];
}

log('fallback:unknown_input', `content=${JSON.stringify(text.slice(0, 80))}`);
return [null, null, null, null, null, msg];

const chatId = msg && msg.payload ? msg.payload.chatId : undefined;
const rawContent = msg && msg.payload ? msg.payload.content : undefined;
const raw = typeof rawContent === 'string' ? rawContent.trim() : '';
const stateKey = `state_${chatId ?? 'unknown'}`;
const MAX_LENGTH = 60;

function log(step, summary) {
    node.warn(`${new Date().toISOString()} | chat=${chatId ?? 'unknown'} | ${step} | ${summary}`);
}

function outgoing(text) {
    msg.payload = {
        type: 'message',
        content: text,
        chatId: chatId,
        inbound: false
    };
    return msg;
}

log('calc:input_received', `value=${JSON.stringify(raw.slice(0, MAX_LENGTH + 1))}`);

if (!raw) {
    log('calc:validation_error', 'reason=empty');
    return [null, outgoing('⚠️ Порожнє повідомлення. Введіть приклад, наприклад: 12 + 7')];
}

if (raw.length > MAX_LENGTH) {
    log('calc:validation_error', `reason=too_long length=${raw.length}`);
    return [null, outgoing(`⚠️ Ввід занадто довгий (${raw.length} символів). Максимум — ${MAX_LENGTH}.` )];
}

// Decimal separator is a dot. Supports unary signs: -5 + 2, 5 * -3.
const match = raw.match(/^([+-]?(?:\d+(?:\.\d*)?|\.\d+))\s*([+\-*/×÷])\s*([+-]?(?:\d+(?:\.\d*)?|\.\d+))$/);

if (!match) {
    log('calc:validation_error', `reason=not_numeric_or_bad_format value=${JSON.stringify(raw.slice(0, 60))}`);
    return [null, outgoing('⚠️ Не вдалося розпізнати приклад. Використайте формат: 12 + 7. Лише числа та +, -, *, /, ×, ÷.')];
}

const a = Number(match[1]);
const op = match[2];
const b = Number(match[3]);

if (!Number.isFinite(a) || !Number.isFinite(b)) {
    log('calc:validation_error', 'reason=non_finite_number');
    return [null, outgoing('⚠️ Одне з чисел некоректне. Спробуйте простіший приклад.')];
}

if ((op === '/' || op === '÷') && b === 0) {
    log('calc:validation_error', 'reason=division_by_zero');
    return [null, outgoing('⚠️ Ділити на нуль не можна. Введіть інший приклад.')];
}

let result;
switch (op) {
    case '+': result = a + b; break;
    case '-': result = a - b; break;
    case '*':
    case '×': result = a * b; break;
    case '/':
    case '÷': result = a / b; break;
    default:
        log('calc:error', `reason=unsupported_operator operator=${op}`);
        return [null, outgoing('⚠️ Непідтримувана операція.')];
}

if (!Number.isFinite(result)) {
    log('calc:error', 'reason=result_not_finite');
    return [null, outgoing('⚠️ Результат не може бути обчислений.')];
}

// Avoid noisy floating point tails in the user-facing result.
const normalized = Number.isInteger(result) ? result : Number(result.toFixed(10));
flow.set(stateKey, null);
log('calc:success', `expression=${a}${op}${b} result=${normalized}`);
return [outgoing(`✅ ${a} ${op} ${b} = ${normalized}`), null];

const chatId = msg && msg.payload ? msg.payload.chatId : undefined;

function log(step, summary) {
    node.warn(`${new Date().toISOString()} | chat=${chatId ?? 'unknown'} | ${step} | ${summary}`);
}

// Set to true only while reproducing the required API-failure log scenario.
const FORCE_NBU_FAILURE = false;

msg.redbotChatId = chatId;
msg.nbuStartedAt = Date.now();
msg.method = 'GET';
msg.url = FORCE_NBU_FAILURE
    ? 'https://bank.gov.ua/NBUStatService/v1/THIS_ENDPOINT_IS_BROKEN?json'
    : 'https://bank.gov.ua/NBUStatService/v1/statdirectory/exchange?json';
msg.payload = '';

log('nbu:request_sent', `url=${msg.url}`);
return msg;

const chatId = msg.redbotChatId;
const elapsed = msg.nbuStartedAt ? Date.now() - msg.nbuStartedAt : null;

function log(step, summary) {
    node.warn(`${new Date().toISOString()} | chat=${chatId ?? 'unknown'} | ${step} | ${summary}`);
}

function outgoing(text) {
    msg.payload = {
        type: 'message',
        content: text,
        chatId: chatId,
        inbound: false
    };
    return msg;
}

const status = Number(msg.statusCode || 0);
if (status < 200 || status >= 300) {
    log('nbu:error', `http_status=${status || 'unknown'} elapsed_ms=${elapsed ?? 'unknown'}`);
    return [null, outgoing('⚠️ Сервіс курсу валют тимчасово недоступний. Спробуйте пізніше або поверніться в меню.')];
}

const data = msg.payload;
if (!Array.isArray(data)) {
    log('nbu:error', `reason=unexpected_response_type status=${status} elapsed_ms=${elapsed ?? 'unknown'}`);
    return [null, outgoing('⚠️ НБУ повернув неочікувану відповідь. Спробуйте пізніше.')];
}

const usd = data.find(item => item && item.cc === 'USD');
const eur = data.find(item => item && item.cc === 'EUR');

if (!usd || !eur || typeof usd.rate !== 'number' || typeof eur.rate !== 'number') {
    log('nbu:error', `reason=usd_or_eur_missing status=${status}`);
    return [null, outgoing('⚠️ Не вдалося знайти курс USD або EUR у відповіді НБУ.')];
}

const date = usd.exchangedate || eur.exchangedate || 'невідомо';
log('nbu:success', `USD=${usd.rate} EUR=${eur.rate} date=${date} elapsed_ms=${elapsed ?? 'unknown'}`);

return [outgoing(
    `💱 Курс НБУ\n` +
    `USD: 1 USD = ${usd.rate.toFixed(4)} UAH\n` +
    `EUR: 1 EUR = ${eur.rate.toFixed(4)} UAH\n` +
    `Дата: ${date}`
), null];

const chatId = msg.redbotChatId || (msg.payload && msg.payload.chatId);
const reason = msg && msg.error && msg.error.message ? msg.error.message : 'transport_error';
node.warn(`${new Date().toISOString()} | chat=${chatId ?? 'unknown'} | nbu:error | reason=${String(reason).slice(0, 160)}`);
msg.payload = {
    type: 'message',
    content: '⚠️ Не вдалося зв’язатися із сервісом НБУ. Спробуйте пізніше.',
    chatId: chatId,
    inbound: false
};
return msg;
